    used_ratio = 1.0 - (remaining / max_cap)
    scores = np.where(valid, np.exp(-5.0 * (remaining / max_cap) ** 2) + used_ratio * 0.1, -np.inf)
    empty_mask = (bins == max_cap) & valid
    if np.any(empty_mask):
        first_empty_idx = np.argmax(empty_mask)
        scores[first_empty_idx] -= 0.3
    return scores}

